import { Box, Group, Stack, Text } from '@mantine/core'
import DriveAssignmentField from './DriveAssignmentField'
import TruncatedText from './TruncatedText'
import FileList from './FileList'
import { LocalFileGroup } from './useFileTree'
import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'

const INDENT_PER_LEVEL = 16

interface Props {
  group: LocalFileGroup
  groupKey: string
  collapsedGroups: Set<string>
  onToggle: (groupKey: string) => void
  assignments: DriveAssignmentsHandle
  inheritedAssignment: DriveAssignment | null
  onPick: (target: PickerTarget) => void
}

export default function GroupNode({ group, groupKey, collapsedGroups, onToggle, assignments, inheritedAssignment, onPick }: Props) {
  const expanded = !collapsedGroups.has(groupKey)
  const own = assignments.groupAssignments.get(groupKey) ?? null
  const effective = own ?? inheritedAssignment

  return (
    <Box>
      <Group gap={8} wrap="nowrap" align="center">
        <button
          type="button"
          onClick={() => onToggle(groupKey)}
          aria-expanded={expanded}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            flex: 1,
            minWidth: 0,
            border: 'none',
            background: 'transparent',
            padding: 0,
            cursor: 'pointer',
            textAlign: 'left',
            fontFamily: 'inherit',
          }}
        >
          <Text size="xs" c="dimmed" style={{ width: 10, flexShrink: 0 }}>{expanded ? '▼' : '▶'}</Text>
          <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        </button>
        <DriveAssignmentField
          label={group.name}
          assignment={effective}
          isOwn={own !== null}
          onPick={() => onPick({ type: 'group', key: groupKey })}
          onClear={() => assignments.clearGroupAssignment(groupKey)}
        />
      </Group>
      {expanded && (
        <Box pl={INDENT_PER_LEVEL}>
          <FileList files={group.files} assignments={assignments} inheritedAssignment={effective} onPick={onPick} />
          {group.subgroups.length > 0 && (
            <Stack gap={8} mt={4}>
              {group.subgroups.map(sub => (
                <GroupNode
                  key={sub.name}
                  group={sub}
                  groupKey={`${groupKey}/${sub.name}`}
                  collapsedGroups={collapsedGroups}
                  onToggle={onToggle}
                  assignments={assignments}
                  inheritedAssignment={effective}
                  onPick={onPick}
                />
              ))}
            </Stack>
          )}
        </Box>
      )}
    </Box>
  )
}

import { useState, useCallback } from 'react'

export interface DriveAssignment {
  driveFolderId: string
  path: string
}

// Identifies what a picked Drive folder should be applied to: a subfolder
// group (by its path key) or an individual file (by its filesystem path).
export type PickerTarget = { type: 'group'; key: string } | { type: 'file'; path: string }

export interface DriveAssignmentsHandle {
  groupAssignments: Map<string, DriveAssignment>
  fileOverrides: Map<string, DriveAssignment>
  setGroupAssignment: (groupKey: string, assignment: DriveAssignment) => void
  clearGroupAssignment: (groupKey: string) => void
  setFileOverride: (filePath: string, assignment: DriveAssignment) => void
  clearFileOverride: (filePath: string) => void
}

// Tracks Drive folder assignments made directly on a subfolder group or on
// an individual file (a file-level assignment overrides its group's).
// Resolving the *effective* assignment for a given group/file (own, else
// inherited from the nearest ancestor group, else none) is the caller's
// job, since only the caller knows the tree structure to walk.
export function useDriveAssignments(): DriveAssignmentsHandle {
  const [groupAssignments, setGroupAssignments] = useState<Map<string, DriveAssignment>>(new Map())
  const [fileOverrides, setFileOverrides] = useState<Map<string, DriveAssignment>>(new Map())

  const setGroupAssignment = useCallback((groupKey: string, assignment: DriveAssignment) => {
    setGroupAssignments(prev => new Map(prev).set(groupKey, assignment))
  }, [])

  const clearGroupAssignment = useCallback((groupKey: string) => {
    setGroupAssignments(prev => {
      const next = new Map(prev)
      next.delete(groupKey)
      return next
    })
  }, [])

  const setFileOverride = useCallback((filePath: string, assignment: DriveAssignment) => {
    setFileOverrides(prev => new Map(prev).set(filePath, assignment))
  }, [])

  const clearFileOverride = useCallback((filePath: string) => {
    setFileOverrides(prev => {
      const next = new Map(prev)
      next.delete(filePath)
      return next
    })
  }, [])

  return { groupAssignments, fileOverrides, setGroupAssignment, clearGroupAssignment, setFileOverride, clearFileOverride }
}

import { Box, Group, Stack, Text, Tooltip } from '@mantine/core'
import DriveAssignmentField from './DriveAssignmentField'
import TruncatedText from './TruncatedText'
import { LocalFile } from './useFileTree'
import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'
import { formatFileSize } from '../../utils'

interface Props {
  files: LocalFile[]
  assignments: DriveAssignmentsHandle
  inheritedAssignment: DriveAssignment | null
  onPick: (target: PickerTarget) => void
}

export default function FileList({ files, assignments, inheritedAssignment, onPick }: Props) {
  return (
    <Stack gap={10} mt={4}>
      {files.map(file => {
        const own = assignments.fileOverrides.get(file.path) ?? null
        const effective = own ?? inheritedAssignment
        return (
          <Box key={file.path} pl={4}>
            <Group gap={8} wrap="nowrap" align="center">
              <Group gap={4} wrap="nowrap" style={{ flex: 1, minWidth: 0 }}>
                <TruncatedText label={file.name} size="sm" c={file.corrupt ? 'red' : undefined}>
                  📄 {file.name}
                </TruncatedText>
                {file.corrupt && (
                  <Tooltip label="Could not read this file — it may be corrupt or not a valid PDF">
                    <span>⚠️</span>
                  </Tooltip>
                )}
              </Group>
              <DriveAssignmentField
                label={file.name}
                assignment={effective}
                isOwn={own !== null}
                onPick={() => onPick({ type: 'file', path: file.path })}
                onClear={() => assignments.clearFileOverride(file.path)}
              />
            </Group>
            <Text size="xs" c="dimmed" mt={2}>
              {file.corrupt ? 'Unreadable' : `${file.pageCount} pages`} · {formatFileSize(file.sizeBytes)}
            </Text>
          </Box>
        )
      })}
    </Stack>
  )
}

